	inline constexpr std::array<std::uint32_t, 10> kRiteQuests{ 0xBEF, 0xBF0, 0xBF1, 0xBF2, 0xBF3, 0xBF4, 0xBF5, 0xBF6, 0xBF7, 0xBF8 };   // the cities' quests in the journal
	struct CurseStep { std::string_view id, title, goal, text; int target; };
	inline constexpr std::array<CurseStep, 4> kCurseSteps{ {
		CurseStep{ "tithe", "The Ashen Tithe", "Slay the risen within {city}", "The dead of {city} rise thickest near {landmark}, drawn to the Dirge like moths to a flame. Every one you put back in the ground loosens the curse's grip on the city. Slay {n} of the risen within {city}'s bounds.", 30 },
		CurseStep{ "wards", "The Ward-Fires of {city}", "Light the ward-fires around the shrine", "Long ago the priests of {city} kept three ward-fires burning against the restless dead, until the Dirge snuffed them out. Three cold braziers now stand around your shrine. Stand by each one until it catches, and keep the dead off you while it does.", 3 },
		CurseStep{ "dawn", "The Vigil of {city}", "Hold the shrine of {city}", "The curse's root lies beneath {city}'s shrine. Stand your ground there while the night throws everything it has at you. Hold the shrine for {n} seconds and the root will crack.", 180 },
		CurseStep{ "herald", "The Herald in the Fog", "Slay the Herald of the Dirge", "Its root cracked, the Dirge calls its Herald: Grimmvar, the Undying Wyrm, who walks only in fog. The next night you face in {city}, the fog will roll in and the Herald will come for you. Slay it before dawn and the city is free.", 1 },
	} };
	enum RiteType : int { kRiteSlay = 0, kRiteWards, kRiteHold, kRiteHerald, kRiteChampion, kRiteRelics, kRiteCircle, kRiteOrder };
