	inline constexpr std::array<std::array<RiteDef, 10>, 10> kRites{ {
		{ { RiteDef{ 5, 4, "The Scattered Bones", "Gather the grave-tokens round {city}", "When the Dirge first sang, Riverwood's old dead were torn from Bleak Falls Barrow and scattered. Four grave-tokens still smoulder where they fell. Grab them before the dead do.", "", "", "", 0.0f }, RiteDef{ 0, 15, "Blood on the River", "Slay the risen within {city}", "The dead come looking for what you took. Put {n} of them back in the ground before they reach the mill.", "", "", "", 0.0f }, RiteDef{ 1, 3, "Lanterns of the Mill", "Light the three mill lanterns", "Hod swears the dead won't cross a lit lantern. Three cold ones hang round your shrine. Stand by each until it catches - and keep your back covered.", "", "", "", 0.0f }, RiteDef{ 2, 45, "Alvor's Anvil", "Hold the shrine of {city}", "Alvor is forging silver for the village with the forge-door barred. Hold the shrine for {n} seconds so the hammer never stops.", "", "", "", 0.0f }, RiteDef{ 5, 3, "Lucan's Golden Claw", "Recover the claw fragments", "The Dirge cracked the Golden Claw's shadow in three and hid the pieces round the village. Lucan will pay - if you live. Find all three.", "", "", "", 0.0f }, RiteDef{ 0, 20, "The Guardian Stones Watch", "Slay the risen within {city}", "The Warrior, the Mage and the Thief are watching. Show them what you are: {n} more dead, no running.", "", "", "", 0.0f }, RiteDef{ 6, 60, "The Barrow Rite", "Keep the dead out of the ritual circle", "The shrine's circle can bind the barrow shut, but only if no dead thing crosses it while it burns. Keep them out for {n} seconds. If they swarm it, it starts again.", "", "", "", 0.0f }, RiteDef{ 7, 4, "Faendal's Arrows", "Kindle the braziers where the arrows fell", "Faendal loosed four fire-arrows into the night - NORTH, then WEST, then SOUTH, then EAST. Light the braziers where they landed, in that order, or the dead hear you.", "NWSE", "", "", 0.0f }, RiteDef{ 0, 25, "The Last Wave", "Slay the risen within {city}", "The barrow is emptying itself into the river. Break the last wave: {n} dead.", "", "", "", 0.0f }, RiteDef{ 4, 1, "The Barrow-Lord", "Slay Hrothgar the Barrow-Lord", "Bound out of his barrow, the Barrow-Lord walks Riverwood himself. Find Hrothgar in the night and end him.", "", "king", "Hrothgar the Barrow-Lord", 25.0f } } },
		{ { RiteDef{ 1, 4, "Kyne's Watchfires", "Light the four watchfires", "Four watchfires once burned for Kyne round the Plains District. Stand by each until it catches, and keep the dead off you while it does.", "", "", "", 0.0f }, RiteDef{ 0, 15, "Trouble at the Drunken Huntsman", "Slay the risen within {city}", "Elrindir has locked the door and is shooting through the window. Help him thin them out: {n} dead.", "", "", "", 0.0f }, RiteDef{ 7, 4, "The Sun's Road", "Kindle the braziers as the sun travels", "Kyne's priests lit their fires the way the sun walks: first EAST, then SOUTH at noon, then WEST, and NORTH last in the dark. Light them out of order and the dead will answer.", "ESWN", "", "", 0.0f }, RiteDef{ 5, 4, "The Gildergreen's Sap", "Gather the glowing sap", "Danica says the Gildergreen bled when the Dirge began. Four drops of its sap glow somewhere in the city. Bring them home.", "", "", "", 0.0f }, RiteDef{ 2, 50, "Skyforge Ringing", "Hold the shrine of {city}", "Eorlund is quenching a blade on the Skyforge and won't stop for the dead. Hold the shrine {n} seconds while the forge rings.", "", "", "", 0.0f }, RiteDef{ 0, 20, "Companions' Hunt", "Slay the risen within {city}", "Aela has called a hunt, and you're the bait. {n} dead before the horn sounds.", "", "", "", 0.0f }, RiteDef{ 6, 60, "Dragonsreach's Shadow", "Keep the dead out of the warding circle", "The court wizard's circle needs one clean minute. Keep every dead thing out of it for {n} seconds.", "", "", "", 0.0f }, RiteDef{ 4, 1, "The Ash-Skald", "Hunt down the Ash-Skald", "A dead bard of Jorrvaskr sings the Dirge in the streets, and the dead dance to it. Shut him up for good.", "", "knight", "The Ash-Skald", 18.0f }, RiteDef{ 0, 25, "The Plains Burn", "Slay the risen within {city}", "The tundra's dead march on the gates. {n} more and the Plains District holds.", "", "", "", 0.0f }, RiteDef{ 3, 1, "The Herald in the Fog", "Slay the Herald of the Dirge", "Whiterun has seen dragons fall. Tonight it watches you. The Dirge sends its Herald out of the fog: whatever great horror walks this night. Slay it before dawn and {city} is free.", "", "", "", 0.0f } } },
		{ { RiteDef{ 0, 15, "The Hangman's Dead", "Slay the risen within {city}", "Everyone who swung from Solitude's gallows has climbed back down. Put {n} of them in the ground for good.", "", "", "", 0.0f }, RiteDef{ 1, 3, "Lamps of the Bards College", "Light the three college lamps", "Viarmo wants the college lamps lit before the Dirge's song drowns out the students. Three lamps, three verses, no dead.", "", "", "", 0.0f }, RiteDef{ 5, 5, "Bones of the Wolf Queen", "Recover the Wolf Queen's bones", "Potema's bones were scattered so she could never rise again. The Dirge is gathering them. Find five pieces before it does.", "", "", "", 0.0f }, RiteDef{ 2, 45, "The Blue Palace Gate", "Hold the shrine of {city}", "Jarl Elisif has sealed the palace. Prove the gate never needed to close: hold the shrine {n} seconds.", "", "", "", 0.0f }, RiteDef{ 7, 4, "The Arch at Dusk", "Kindle the braziers as the Arch lights", "The lamps along the great Arch are lit from the sea up: WEST, NORTH, EAST, SOUTH. Follow the old lamplighter's path.", "WNES", "", "", 0.0f }, RiteDef{ 0, 20, "East Empire Docks", "Slay the risen within {city}", "Drowned sailors are crawling out of the harbour. {n} of them, and the cargo is safe.", "", "", "", 0.0f }, RiteDef{ 4, 1, "Potema's Last Thrall", "Destroy Potema's Last Thrall", "Her last thrall still serves her and raises the dead in her name. Destroy it.", "", "lich", "Potema's Last Thrall", 22.0f }, RiteDef{ 5, 3, "The Emperor's Seals", "Recover the imperial seals", "Three imperial seals were lost when Castle Dour's dead broke loose. Find them before the Legion notices.", "", "", "", 0.0f }, RiteDef{ 6, 75, "The Queen's Requiem", "Keep the dead out of the requiem circle", "Sing her down. The priests' circle must burn for {n} seconds with no dead inside it. If they break it, it starts again.", "", "", "", 0.0f }, RiteDef{ 3, 1, "The Herald in the Fog", "Slay the Herald of the Dirge", "Potema's shadow is broken. Only her master is left. The Dirge sends its Herald out of the fog: whatever great horror walks this night. Slay it before dawn and {city} is free.", "", "", "", 0.0f } } },
		{ { RiteDef{ 7, 4, "The Five Hundred's Fires", "Kindle the braziers in Ysgramor's order", "Ysgramor's companions lit their fires from the sea: NORTH where the ships came in, then EAST, then SOUTH, then WEST. Keep their order or the dead come.", "NESW", "", "", 0.0f }, RiteDef{ 0, 15, "The Grey Quarter's Dead", "Slay the risen within {city}", "The dead are thick in the narrow streets. Slay {n} of them before they reach the Cornerclub.", "", "", "", 0.0f }, RiteDef{ 5, 4, "The Butcher's Trophies", "Recover the stolen remains", "Somebody - something - is collecting pieces of Windhelm's dead again. Four grisly trophies are hidden round the city. Find them.", "", "", "", 0.0f }, RiteDef{ 1, 3, "Candlehearth Flames", "Light the three hearth flames", "Elda swears the Candlehearth's flame has burned since the city was built. Carry it to three cold braziers round your shrine.", "", "", "", 0.0f }, RiteDef{ 0, 20, "The Frozen Docks", "Slay the risen within {city}", "The dead are walking across the frozen river. Break {n} of them on the ice.", "", "", "", 0.0f }, RiteDef{ 2, 60, "Stand at Ysgramor's Shrine", "Hold the shrine of {city}", "Stand your ground at the shrine while the night throws everything at you. Hold it for {n} seconds.", "", "", "", 0.0f }, RiteDef{ 6, 60, "The Palace of the Kings", "Keep the dead out of the royal circle", "Ulfric's housecarls have drawn a circle in salt. Keep it clean of dead for {n} seconds.", "", "", "", 0.0f }, RiteDef{ 5, 3, "Ysgramor's Teeth", "Find the war-horn fragments", "Three fragments of an old war-horn lie scattered round the city. Together they could still make the dead flinch.", "", "", "", 0.0f }, RiteDef{ 0, 25, "The White River Rises", "Slay the risen within {city}", "The river gives up its dead all at once. {n} more and Windhelm stands.", "", "", "", 0.0f }, RiteDef{ 4, 1, "The Frost-Jarl", "Slay the Frost-Jarl Hrolvar", "A jarl of the old Kings walks again, frozen and furious. Find Hrolvar in the night and break him.", "", "king", "Frost-Jarl Hrolvar", 30.0f } } },
		{ { RiteDef{ 5, 5, "The Tonal Keys", "Find the Dwemer tonal keys", "Five Dwemer tonal keys lie about the city. Together they can tune the old resonator against the Dirge. Find them.", "", "", "", 0.0f }, RiteDef{ 0, 15, "The Warrens' Dead", "Slay the risen within {city}", "The Warrens' poor were buried in the rock, and now they're climbing out. Lay {n} of them to rest.", "", "", "", 0.0f }, RiteDef{ 1, 3, "Steam Vents of the Dwemer", "Open the three steam vents", "Old Dwemer vents can scald the dead off the stairways. Wake three of them - stand close, it takes a moment.", "", "", "", 0.0f }, RiteDef{ 6, 60, "The Tonal Resonator", "Keep the dead out of the resonator's circle", "The resonator hums at your shrine. Keep the dead out of its circle for {n} seconds while it tunes the stone against the Dirge.", "", "", "", 0.0f }, RiteDef{ 0, 20, "Cidhna Breakout", "Slay the risen within {city}", "The dead of Cidhna Mine have broken their chains. Put {n} of them back underground.", "", "", "", 0.0f }, RiteDef{ 7, 4, "The Forsworn Totems", "Kindle the totems in the Reach order", "The Forsworn burn their totems SOUTH to NORTH, then EAST to WEST. Get it wrong and the Reach itself answers.", "SNEW", "", "", 0.0f }, RiteDef{ 2, 50, "The Hall of the Dead", "Hold the shrine of {city}", "Brother Verulus is sealing the catacombs. Hold the shrine {n} seconds and not one more corpse leaves the Hall.", "", "", "", 0.0f }, RiteDef{ 4, 1, "The Witch-Bones", "Destroy the Forsworn Witch-Bones", "A briarheart witch, long dead, raises the Reach's dead against the city. Destroy her.", "", "wailer", "The Forsworn Witch-Bones", 22.0f }, RiteDef{ 0, 25, "Silver-Blood Debt", "Slay the risen within {city}", "Thonar Silver-Blood is paying in silver for every corpse. Collect: {n} dead.", "", "", "", 0.0f }, RiteDef{ 3, 1, "The Herald in the Fog", "Slay the Herald of the Dirge", "The stone city has gone quiet. Something enormous is listening. The Dirge sends its Herald out of the fog: whatever great horror walks this night. Slay it before dawn and {city} is free.", "", "", "", 0.0f } } },
		{ { RiteDef{ 0, 15, "Rats in the Ratway", "Slay the risen within {city}", "The Ratway is crawling with the dead. Clear {n} of them before they reach the market.", "", "", "", 0.0f }, RiteDef{ 5, 4, "Brynjolf's Mark", "Lift the four purses", "Brynjolf bets you can't lift four purses off the dead mid-fight. Prove him wrong - they're scattered round the city.", "", "", "", 0.0f }, RiteDef{ 1, 3, "Mara's Candles", "Light Mara's three candles", "Maramal says the dead hate love more than fire. Light three of Mara's candles round your shrine.", "", "", "", 0.0f }, RiteDef{ 4, 1, "The Nightingale's Shade", "Hunt the Nightingale's Shade", "A Nightingale who failed her oath stalks the canals, fast as a knife. Catch her if you can.", "", "runner", "The Nightingale's Shade", 20.0f }, RiteDef{ 2, 45, "The Bee and Barb", "Hold the shrine of {city}", "Keerava has bet the tavern you'll hold the shrine {n} seconds. Don't make her pay.", "", "", "", 0.0f }, RiteDef{ 0, 20, "Honningbrew Dead", "Slay the risen within {city}", "The canal is choked with drowned dead. Fish out {n} of them.", "", "", "", 0.0f }, RiteDef{ 5, 5, "Nocturnal's Keys", "Find Nocturnal's keys", "Five keys of the Twilight Sepulcher are scattered round Riften. Nocturnal wants them back - and she'll return the favour.", "", "", "", 0.0f }, RiteDef{ 6, 60, "The Black-Briar Ward", "Keep the dead out of the ward circle", "Maven paid for this circle and expects results. Keep the dead out of it for {n} seconds.", "", "", "", 0.0f }, RiteDef{ 7, 4, "The Canal Locks", "Open the locks in the right order", "The canal locks open EAST, NORTH, WEST, SOUTH. Open them out of order and the dead flood in.", "ENWS", "", "", 0.0f }, RiteDef{ 2, 75, "The Long Night", "Hold the shrine of {city}", "The darkest night Riften has known. Hold the shrine for {n} seconds and the Dirge's grip breaks.", "", "", "", 0.0f } } },
		{ { RiteDef{ 1, 4, "Arkay's Grave-Candles", "Light the four grave-candles", "Runil keeps grave-candles for every soul in Falkreath's yard. Four have gone out. Light them.", "", "", "", 0.0f }, RiteDef{ 0, 15, "The Graveyard Shift", "Slay the risen within {city}", "The graveyard is emptying faster than Runil can bury. Help him: {n} dead.", "", "", "", 0.0f }, RiteDef{ 5, 5, "The Restless Graves", "Lay the restless grave-markers", "The dead of {city} pulled up their own grave-markers. Find five and set them back.", "", "", "", 0.0f }, RiteDef{ 2, 45, "Dead Man's Drink", "Hold the shrine of {city}", "Valga has promised a free round to whoever holds the shrine {n} seconds. Earn your mead.", "", "", "", 0.0f }, RiteDef{ 7, 4, "The Tolling Order", "Kindle the braziers in the tolling order", "Falkreath's funeral bell tolls SOUTH, WEST, NORTH, EAST. Kindle the braziers in that order and the dead must listen.", "SWNE", "", "", 0.0f }, RiteDef{ 0, 20, "Hunters' Moon", "Slay the risen within {city}", "The forest's dead are coming out of the pines. {n} more for the hunters' tally.", "", "", "", 0.0f }, RiteDef{ 6, 60, "The Lone Coffin", "Keep the dead out of the vigil circle", "A coffin nobody remembers burying sits in your circle. Keep the dead away from it for {n} seconds.", "", "", "", 0.0f }, RiteDef{ 5, 3, "Dengeir's Secrets", "Find the old jarl's letters", "The old jarl hid three letters about what really lies under the graveyard. Find them - quickly.", "", "", "", 0.0f }, RiteDef{ 0, 25, "The Yard Overflows", "Slay the risen within {city}", "Every grave is open at once. {n} dead and it's finally quiet.", "", "", "", 0.0f }, RiteDef{ 4, 1, "The Gravewarden", "Slay the Gravewarden", "The graveyard's first keeper has come back to keep it his way. Put the Gravewarden down.", "", "knight", "The Gravewarden", 28.0f } } },
		{ { RiteDef{ 6, 60, "The Marsh Vigil", "Keep the dead out of the vigil circle", "Keep the dead out of the vigil circle for {n} seconds while the marsh lights burn.", "", "", "", 0.0f }, RiteDef{ 0, 15, "Drowned Dead", "Slay the risen within {city}", "The marsh is giving up its drowned. Slay {n} of them before they reach the longhouses.", "", "", "", 0.0f }, RiteDef{ 5, 4, "Falion's Charms", "Gather the warding charms", "Falion hung four warding charms on the boardwalks, and the dead tore them down. Find them.", "", "", "", 0.0f }, RiteDef{ 1, 3, "Swamp-Lights", "Light the three swamp-lights", "Will-o'-the-wisps lead the dead astray. Light three swamp-lights round your shrine and let them wander.", "", "", "", 0.0f }, RiteDef{ 0, 20, "The Moorside Brawl", "Slay the risen within {city}", "Jonna has barricaded the Moorside and handed out cleavers. Help her break {n} dead.", "", "", "", 0.0f }, RiteDef{ 7, 4, "The Fog Bells", "Ring the fog bells in order", "Morthal's fog bells ring NORTH, SOUTH, EAST, WEST. Ring them wrong and the marsh answers.", "NSEW", "", "", 0.0f }, RiteDef{ 4, 1, "Movarth's Blood-Thrall", "Destroy Movarth's Blood-Thrall", "Movarth's last thrall hunts the boardwalks. Destroy it.", "", "bloater", "Movarth's Blood-Thrall", 22.0f }, RiteDef{ 2, 50, "Highmoon Hall", "Hold the shrine of {city}", "Jarl Idgrod has seen this night in a vision: you, holding the shrine {n} seconds. Make it true.", "", "", "", 0.0f }, RiteDef{ 0, 25, "The Marsh Rises", "Slay the risen within {city}", "The whole marsh stands up at once. {n} more.", "", "", "", 0.0f }, RiteDef{ 3, 1, "The Herald in the Fog", "Slay the Herald of the Dirge", "The fog thickens over the marsh. Something walks in it. The Dirge sends its Herald out of the fog: whatever great horror walks this night. Slay it before dawn and {city} is free.", "", "", "", 0.0f } } },
		{ { RiteDef{ 5, 5, "Shards of the Nightmare", "Gather the nightmare shards", "Five shards of Vaermina's nightmare lie frozen round the harbour. Gather them before the town sleeps again.", "", "", "", 0.0f }, RiteDef{ 0, 15, "Sleepless Dead", "Slay the risen within {city}", "The dead of {city} never got to sleep. Give {n} of them the rest they want.", "", "", "", 0.0f }, RiteDef{ 1, 3, "Harbour Beacons", "Light the three harbour beacons", "The ships are blind in the fog. Light three beacons round your shrine and bring them home.", "", "", "", 0.0f }, RiteDef{ 7, 4, "The Dreamer's Path", "Kindle the braziers along the dreamer's path", "Erandur walks the dreamer's path: WEST, NORTH, EAST, SOUTH. Follow it exactly.", "WNES", "", "", 0.0f }, RiteDef{ 0, 20, "The Iron-Breaker Mine", "Slay the risen within {city}", "Miners are climbing out of the Iron-Breaker who should never have gone in. {n} of them, now.", "", "", "", 0.0f }, RiteDef{ 2, 45, "Windpeak Inn", "Hold the shrine of {city}", "Thoring has barred the inn and is pouring for anyone who holds the shrine {n} seconds.", "", "", "", 0.0f }, RiteDef{ 4, 1, "Vaermina's Hound", "Hunt Vaermina's Hound", "Something with too many teeth prowls the frozen harbour. Hunt Vaermina's Hound.", "", "bloater", "Vaermina's Hound", 22.0f }, RiteDef{ 5, 3, "Skooma Dreams", "Find the stolen dream-salts", "Three pouches of dream-salt went missing from the Nightcaller Temple. Whoever finds the dead holding them, finds them.", "", "", "", 0.0f }, RiteDef{ 0, 25, "The Long Dark", "Slay the risen within {city}", "The sun won't rise until {n} more are down.", "", "", "", 0.0f }, RiteDef{ 6, 75, "Wake the Town", "Keep the dead out of the waking circle", "Keep the dead out of the waking circle for {n} seconds and Dawnstar wakes for good.", "", "", "", 0.0f } } },
		{ { RiteDef{ 1, 4, "The Magnus Lights", "Light the four Magnus lights", "Four lamps once burned with Magnus' light along the cliff. Light them again.", "", "", "", 0.0f }, RiteDef{ 0, 15, "The Cliff Dead", "Slay the risen within {city}", "The dead of drowned Winterhold climb the cliffs. Push {n} of them back into the sea.", "", "", "", 0.0f }, RiteDef{ 5, 5, "Lost Pages of the College", "Recover the College's lost pages", "Urag gro-Shub wants his pages back. Five of them blew across the town when the Dirge struck.", "", "", "", 0.0f }, RiteDef{ 2, 45, "The Frozen Hearth", "Hold the shrine of {city}", "Dagur has kept the Frozen Hearth's fire going for days. Hold the shrine {n} seconds so he can sleep.", "", "", "", 0.0f }, RiteDef{ 0, 20, "Apprentice Trouble", "Slay the risen within {city}", "A college apprentice raised far more than he meant to. Clean up: {n} dead.", "", "", "", 0.0f }, RiteDef{ 7, 4, "The Eye of Magnus", "Kindle the braziers as the Eye turned", "The Eye of Magnus turned EAST, SOUTH, WEST, NORTH. Light the braziers the way it looked.", "ESWN", "", "", 0.0f }, RiteDef{ 4, 1, "The Drowned Archmage", "Destroy the Drowned Archmage", "An Archmage lost with old Winterhold has walked out of the sea. Destroy him.", "", "lich", "The Drowned Archmage", 24.0f }, RiteDef{ 6, 60, "Arcanaeum Seal", "Keep the dead out of the sealing circle", "Tolfdir's seal needs {n} seconds without a dead thing inside it.", "", "", "", 0.0f }, RiteDef{ 0, 25, "The Great Collapse", "Slay the risen within {city}", "Every soul lost in the Great Collapse is walking tonight. {n} more.", "", "", "", 0.0f }, RiteDef{ 2, 75, "The Last Stand of Winterhold", "Hold the shrine of {city}", "Hold the shrine for {n} seconds. Winterhold has fallen before. Not tonight.", "", "", "", 0.0f } } },
	} };
	inline constexpr std::uint32_t kCurseIntroGlobal = 0x996, kStandLayoutGlobal = 0x9DB, kDirgeBook = 0x9DC;
	inline constexpr std::string_view kCursePrologueTitle = "THE UNDYING DIRGE", kCursePrologue = "Helgen burned, and you lived. But as the World-Eater rose from the ash he sang a word older than the Thu'um: the Undying Dirge. Every grave in Skyrim heard it. Now when the sun goes down, the dead claw their way up to finish what he began. The Dirge has taken root in the cities of the holds. Break it, city by city, and their dead will sleep again.", kCurseLiftedBanner = "THE CURSE OVER {CITY} IS BROKEN", kCurseLiftedText = "The Dirge's root beneath {city} shatters. Its dead sleep again: no undead will rise within its bounds.", kCurseFreedAll = "Every city of Skyrim stands free of the Dirge. Its echo lingers only in the wild places, and it will not fall silent until the World-Eater does.";
	inline constexpr float kCurseZone = 6500.0f, kCurseHoldRadius = 900.0f, kCurseWardRadius = 150.0f, kCurseWardSeconds = 5.0f, kCurseWardDistance = 650.0f, kCurseHeraldDelay = 20.0f;
	inline constexpr std::uint32_t kWardBrazier = 0x997, kWardFire = 0x998, kWardLight = 0x999;
	enum SpellTap : int { kTapBolt = 0, kTapFan, kTapChain, kTapGust, kTapWisp };
